   63			if i < 0 {
   64				return nil, &SyntaxError{Line: n, Text: line}
   65			}
   66			key := strings.ToLower(strings.TrimSpace(line[:i]))
   67			val := strings.TrimSpace(line[i+1:])
   68			if j := strings.Index(val, ";"); j >= 0 {
   69				val = strings.TrimSpace(val[:j])
   70			}
   71			if len(val) >= 2 && val[0] == '"' && val[len(val)-1] == '"' {
   72				val = strings.TrimSpace(val[1 : len(val)-1])
   73			}
   74			if f[section] == nil {
   75				f[section] = map[string]string{}
   76			}
   77			if _, exists := f[section][key]; !exists {
   78				f[section][key] = val
   79			}
   80		}
   81		return f, sc.Err()
   82	}

